\documentclass[border=5mm]{standalone}
\usepackage{pgfplots}
\usepackage{tikz}
\usetikzlibrary{calc, arrows, intersections, fillbetween}

\begin{document}

\pagestyle{empty}

% Colors
\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

\newcommand{\mydot}[2]{
    \node[circle, draw=none, fill=#2, inner sep=1.5pt] at (axis cs:#1) {};
}

\begin{tikzpicture}[declare function={f(\x)=3*\x+28;}]

\begin{axis}[
%clip=false,
enlargelimits=false,
tick label style={font=\footnotesize},
label style={font=\small},
tick style={draw=black,thick}, minor tick style={draw=none},
axis line style = thick,
axis y line = middle, axis x line = middle,
%axis equal,
grid = both, grid style={thin, color=lightgray!50},
xmin = 0, xmax = 10,
%axis x discontinuity=crunch, %crunch|parallel|none
ymin = 20, ymax = 60,
axis y discontinuity=crunch, %crunch|parallel|none
xtick = {2,4,...,8}, %xticklabels = {,,},
ytick = {20,30,...,50}, %yticklabels = {,,},
minor xtick={1,2,...,10},
minor ytick={20,25,...,60},   
xlabel = {Time (decades)}, ylabel = {Cost (thousands of \$)},
x label style={at={(axis description cs:0.5,-0.1)},anchor=north},
y label style={at={(axis description cs:-0.1,.5)},rotate=90,anchor=south},
]

% Random seed
\pgfmathsetseed{1}

% Closer to 0 -> more linear 
\def\spread{7}

% Trend Line
\plot[domain=0.5:9.5, variable=\x, orangepeel, very thick]{f(\x)};

% Blob
\foreach \x [evaluate=\x as \y using f(\x)] in {1,1.5,...,3.5}{
	\edef\temp{
		\noexpand
		\node[circle, draw=none, fill=deepskyblue, inner sep=1.5pt] at (axis cs: \x, \y+rand*\spread) {};
	}\temp
}
\foreach \x [evaluate=\x as \y using f(\x)] in {4.5,5.0,...,9}{
	\edef\temp{
		\noexpand
		\node[circle, draw=none, fill=deepskyblue, inner sep=1.5pt] at (axis cs: \x, \y+rand*\spread) {};
	}\temp
}

\draw[->, fadedpink, thick, shorten <        = 1.5mm, shorten >= 1.5mm] (axis cs:7,-4) -- (axis cs:7,-2) node[circle, inner sep=2pt, draw=none, fill=red] {};

\draw[->, fadedpink, thick, shorten <        = 1.5mm, shorten >= 1.5mm] (axis cs:4,40) -- (axis cs:4,35) node[circle, inner sep=2pt, draw=none, fill=red] {};

\end{axis}

\end{tikzpicture}
\end{document}

